layer.css:
[data-ryt="pitch"] { color: var(--ryt-text); background-color: rgb(246, 246, 246); border-left: 8px solid rgb(237, 237, 237); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16.8px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 33.6px; padding-right: 33.6px; padding-bottom: 33.6px; padding-left: 33.6px; transition: all; border-top: none; border-right: none; border-bottom: none }
[data-ryt="footer"] { color: var(--ryt-text); background-color: var(--ryt-surface); border-top: 3px solid rgb(238, 238, 238); font-style: normal; letter-spacing: normal; text-transform: none }
article[data-ryt="rec-card"] { background-color: var(--ryt-surface); border-radius: 4px; box-shadow: rgba(0, 0, 0, 0.2) 0px 1px 2px 0px; transition: all; position: relative }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: 0.2s ease-in-out }
[data-ryt="brand"] { color: #8a8a8a; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 32.5px; font-weight: 300; font-style: normal; line-height: 1.3; letter-spacing: -1px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; transition: 0.2s ease-in-out }
[data-ryt="category"], [data-ryt="tags"] li { color: #818181; border-radius: 0px; font-family: var(--ryt-font-body); font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: 1px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: rgb(153, 153, 153); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: 0.2s ease-in-out }
[data-ryt="review"] { color: var(--ryt-text); font-family: var(--ryt-font-body); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: #818181; font-family: var(--ryt-font-body); font-size: 13.2px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: 1px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: rgb(153, 153, 153); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 300; font-style: normal; letter-spacing: -1px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: 0.2s ease-in-out }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 28px; font-weight: 300; font-style: normal; line-height: 1.2; letter-spacing: -1px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { color: var(--ryt-accent); color: var(--ryt-accent); text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="credit"]::before, [data-ryt="eyebrow"]::before { content: ""; display: inline; color: rgb(153, 153, 153); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: var(--ryt-font-body); font-size: 13.2px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: 1px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: rgb(153, 153, 153); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: rgb(153, 153, 153) }
[data-ryt="category"]:hover, [data-ryt="tags"] li:hover { color: var(--ryt-accent); color: var(--ryt-accent); text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="brand"]:hover { color: var(--ryt-accent) }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { color: var(--ryt-accent); text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
article[data-ryt="rec-card"]::before { content: ""; display: block; position: absolute; color: var(--ryt-text); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-top: 11px solid rgba(0, 0, 0, 0); border-right: 11px solid rgb(221, 221, 221); border-bottom: 11px solid rgba(0, 0, 0, 0); border-left: 11px solid rgba(0, 0, 0, 0); border-radius: 0px; font-family: var(--ryt-font-body); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: var(--ryt-text); top: 49px; left: -12px }
article[data-ryt="rec-card"]::after { content: ""; display: block; position: absolute; color: var(--ryt-text); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-top: 10px solid rgba(0, 0, 0, 0); border-right: 10px solid var(--ryt-surface); border-bottom: 10px solid rgba(0, 0, 0, 0); border-left: 10px solid rgba(0, 0, 0, 0); border-radius: 0px; font-family: var(--ryt-font-body); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: var(--ryt-text); top: 50px; left: -12px }
